from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFF = sum(nums)
        if abs(k) > OFF:
            return -1
        dp = {}  # product -> [mask_parity0, mask_parity1]; -1 key means "over limit"
        for x in nums:
            add = {}
            # start new subsequence with x (first element, even index -> +x)
            if x == 0:
                npx = 0
            else:
                npx = x if x <= limit else -1
            e = add.get(npx)
            if e is None:
                e = [0, 0]
                add[npx] = e
            e[1] |= 1 << (x + OFF)
            for p, ms in dp.items():
                m0 = ms[0]
                m1 = ms[1]
                if not m0 and not m1:
                    continue
                if x == 0:
                    np = 0
                elif p == -1:
                    np = -1
                else:
                    v = p * x
                    np = v if v <= limit else -1
                e = add.get(np)
                if e is None:
                    e = [0, 0]
                    add[np] = e
                if m0:
                    # current length even -> next element at even index -> +x, parity becomes 1
                    e[1] |= m0 << x
                if m1:
                    # current length odd -> next element at odd index -> -x, parity becomes 0
                    e[0] |= m1 >> x
            for p, a in add.items():
                d = dp.get(p)
                if d is None:
                    dp[p] = a
                else:
                    d[0] |= a[0]
                    d[1] |= a[1]
        best = -1
        bit = k + OFF
        for p, ms in dp.items():
            if p == -1:
                continue
            if p <= best:
                continue
            if ((ms[0] | ms[1]) >> bit) & 1:
                best = p
        return best

