class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N):
            if N <= 0:
                return 0
            s = str(N)
            n = len(s)

            @lru_cache(None)
            def dp(pos, tight, started, sm, pr):
                if pos == n:
                    if not started:
                        return 0
                    return 1 if pr % sm == 0 else 0
                res = 0
                hi = int(s[pos]) if tight else 9
                for d in range(0, hi + 1):
                    nt = tight and (d == hi)
                    if not started and d == 0:
                        res += dp(pos + 1, nt, False, 0, 1)
                    else:
                        res += dp(pos + 1, nt, True, sm + d, pr * d)
                return res

            ans = dp(0, True, False, 0, 1)
            dp.cache_clear()
            return ans

        return count(r) - count(l - 1)

