        edges.append((u,v))

    INF = 10**9

    class Dinic:
        def __init__(self, n):
            self.n = n
            self.graph = [[] for _ in range(n)]
        def add_edge(self, fr, to, cap):
            forward = [to, cap, None]
            backward = [fr, 0, None]
            forward[2] = backward
            backward[2] = forward
            self.graph[fr].append(forward)
            self.graph[to].append(backward)
        def bfs(self, s, t):
            self.level = [-1]*self.n
            self.level[s] = 0
            q = deque([s])
            while q:
                u = q.popleft()
                for e in self.graph[u]:
                    if e[1] > 0 and self.level[e[0]] < 0:
                        self.level[e[0]] = self.level[u]+1
                        q.append(e[0])
            return self.level[t] >= 0
        def dfs(self, s, t, limit):
            # iterative dfs to find augmenting path
            stack = [s]
            path = []
            while stack:
                u = stack[-1]
                if u == t:
                    # find min cap
                    f = limit
                    for e in path:
                        if e[1] < f: f = e[1]
                    for e in path:
                        e[1] -= f
                        e[2][1] += f
                    return f
                advanced = False
                while self.it[u] < len(self.graph[u]):
                    e = self.graph[u][self.it[u]]
                    if e[1] > 0 and self.level[e[0]] == self.level[u]+1:
                        stack.append(e[0])
                        path.append(e)
                        advanced = True
                        break
                    else:
                        self.it[u] += 1
                if not advanced:
                    self.level[u] = -1
                    stack.pop()
                    if path:
                        path.pop()
                    if stack:
                        self.it[stack[-1]] += 1
            return 0
        def max_flow(self, s, t, limit_stop):
            flow = 0
            while self.bfs(s, t):
                self.it = [0]*self.n
                while True:
                    f = self.dfs(s, t, INF)
                    if f == 0:
                        break
                    flow += f
                    if flow > limit_stop:
                        return flow
            return flow

    def mincost(D):
        # nodes: (v,i) v in 1..N, i in 1..D  -> (v-1)*D + (i-1)
        total = N*D + 2
        S = N*D
        T = N*D + 1
        din = Dinic(total)
        def nid(v, i):
            return (v-1)*D + (i-1)
        # monotone
        for v in range(1, N+1):
            for i in range(1, D):
                din.add_edge(nid(v,i), nid(v,i+1), INF)
        for (u,v) in edges:
            for i in range(1, D+1):
                din.add_edge(nid(u,i), nid(v,i), 1)
            for i in range(2, D+1):
                din.add_edge(nid(u,i-1), nid(v,i), INF)
        for i in range(1, D+1):
            din.add_edge(S, nid(1,i), INF)
            din.add_edge(nid(N,i), T, INF)
        return din.max_flow(S, T, K)

    best = 0
    for D in range(1, N):
        c = mincost(D)
        if c <= K:
            best = D
        else:
            break
    print(best)

