class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [i for i in range(1, n+1) if i % 2 == 1]
        evens = [i for i in range(1, n+1) if i % 2 == 0]
        o = len(odds)
        e = len(evens)
        oi = 0  # index into odds (smallest unused)
        ei = 0
        used_o = 0
        used_e = 0

        def count_after(rem_o, rem_e, next_parity):
            # next_parity: 1 for odd required next, 0 for even, None if no positions left
            rem = rem_o + rem_e
            if rem == 0:
                return 1
            if next_parity == 1:
                need_o = (rem + 1) // 2
                need_e = rem // 2
            else:
                need_e = (rem + 1) // 2
                need_o = rem // 2
            if need_o != rem_o or need_e != rem_e:
                return 0
            return factorial(rem_o) * factorial(rem_e)

        # total check
        total = 0
        # position 0 handled in loop
        res = []
        rem_o = o
        rem_e = e
        prev_parity = None
        # available lists as sorted lists; use pointers per parity
        odd_ptr = 0
        even_ptr = 0
        odds_used = [False]*len(odds)
        evens_used = [False]*len(evens)

        for pos in range(n):
            if prev_parity is None:
                parities = [1, 0]
            else:
                parities = [1 - prev_parity]
            # candidates sorted ascending overall
            cands = []
            for p in parities:
                if p == 1:
                    for idx in range(len(odds)):
                        if not odds_used[idx]:
                            cands.append((odds[idx], 1, idx))
                else:
                    for idx in range(len(evens)):
                        if not evens_used[idx]:
                            cands.append((evens[idx], 0, idx))
            cands.sort()
            placed = False
            for val, p, idx in cands:
                nro = rem_o - (1 if p == 1 else 0)
                nre = rem_e - (0 if p == 1 else 1)
                nxt = 1 - p
                c = count_after(nro, nre, nxt)
                if k > c:
                    k -= c
                else:
                    res.append(val)
                    if p == 1:
                        odds_used[idx] = True
                    else:
                        evens_used[idx] = True
                    rem_o = nro
                    rem_e = nre
                    prev_parity = p
                    placed = True
                    break
            if not placed:
                return []
        return res

