                d2 = out_masks[p]
                if ch in d2:
                    d2[ch] |= (1 << q)
                else:
                    d2[ch] = (1 << q)

    FULL = (1 << n) - 1
    unvisited = [FULL] * n
    dist = [[-1]*n for _ in range(n)]

    q = deque()
    # level 0
    for i in range(n):
        dist[i][i] = 0
        unvisited[i] &= ~(1 << i)
        q.append((i, i, 0))
    # level 1
