class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # next required value: after 1 -> 2, after 2 -> 0, after 0 -> 2
        nxtv = [[(0 if grid[i][j] == 2 else 2) for j in range(m)] for i in range(n)]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order

        G = []
        for d in range(4):
            di, dj = dirs[d]
            g = [[1] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if di == 1 else range(n)
            cols = list(range(m - 1, -1, -1)) if dj == 1 else list(range(m))
            for i in rows:
                ni = i + di
                if 0 <= ni < n:
                    grow = g[i]
                    gnrow = g[ni]
                    nvrow = nxtv[i]
                    gnr = grid[ni]
                    for j in cols:
                        nj = j + dj
                        if 0 <= nj < m and gnr[nj] == nvrow[j]:
                            grow[j] = 1 + gnrow[nj]
            G.append(g)

        ones = []
        for i in range(n):
            gri = grid[i]
            for j in range(m):
                if gri[j] == 1:
                    ones.append((i, j))
        if not ones:
            return 0

        best = 0
        for d in range(4):
            di, dj = dirs[d]
            cd = (d + 1) % 4
            cdi, cdj = dirs[cd]
            gc = G[cd]
            t = [[1] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if di == 1 else range(n)
            cols = list(range(m - 1, -1, -1)) if dj == 1 else list(range(m))
            for i in rows:
                ni = i + di
                ci = i + cdi
                trow = t[i]
                nvrow = nxtv[i]
                if 0 <= ni < n:
                    trn = t[ni]
                    grn = grid[ni]
                else:
                    trn = None
                    grn = None
                if 0 <= ci < n:
                    gcr = gc[ci]
                    gcgrid = grid[ci]
                else:
                    gcr = None
                    gcgrid = None
                for j in cols:
                    v = 1
                    need = nvrow[j]
                    if trn is not None:
                        nj = j + dj
                        if 0 <= nj < m and grn[nj] == need:
                            v = 1 + trn[nj]
                    if gcr is not None:
                        cj = j + cdj
                        if 0 <= cj < m and gcgrid[cj] == need:
                            w = 1 + gcr[cj]
                            if w > v:
                                v = w
                    trow[j] = v
            for (i, j) in ones:
                val = t[i][j]
                if val > best:
                    best = val
        return best

