class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        # precompute permutations for mod 7 transition
        perms = []
        for d in range(10):
            p = [0]*7
            for r in range(7):
                p[(3*r + d) % 7] = r
            perms.append(p)
        cnt7 = [0]*7
        c3 = [0,0,0]
        c9 = [0]*9
        c3[0] = 1
        c9[0] = 1
        ps = 0
        total = 0
        for j in range(n):
            d = ord(s[j]) - 48
            # update mod-7 counts
            p = perms[d]
            cnt7 = [cnt7[p[0]], cnt7[p[1]], cnt7[p[2]], cnt7[p[3]], cnt7[p[4]], cnt7[p[5]], cnt7[p[6]]]
            cnt7[d % 7] += 1
            ps += d
            r3 = ps % 3
            r9 = ps % 9
            if d == 0:
                pass
            elif d == 1 or d == 2 or d == 5:
                total += j + 1
            elif d == 3 or d == 6:
                total += c3[r3]
            elif d == 9:
                total += c9[r9]
            elif d == 7:
                total += cnt7[0]
            elif d == 4:
                total += 1
                if j >= 1:
                    t = (ord(s[j-1]) - 48) * 10 + 4
                    if t % 4 == 0:
                        total += j
            elif d == 8:
                total += 1
                if j >= 1:
                    t2 = (ord(s[j-1]) - 48) * 10 + 8
                    if t2 % 8 == 0:
                        total += 1
                    if j >= 2:
                        t3 = (ord(s[j-2]) - 48) * 100 + t2
                        if t3 % 8 == 0:
                            total += j - 1
            c3[r3] += 1
            c9[r9] += 1
        return total

