class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def ok(T):
            if T == 0:
                return True
            total = 0
            prev = 0
            for i in range(n):
                p = points[i]
                need = -(-T // p) - prev
                if need <= 0:
                    total += 1
                    prev = 0
                else:
                    total += 2 * need - 1
                    prev = need - 1
                if total > m:
                    return False
            return total <= m

        lo, hi = 0, m * max(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

