class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        full = 1 << m
        lcms = [1]*full
        for mask in range(1, full):
            l = 1
            for i in range(m):
                if mask >> i & 1:
                    t = target[i]
                    l = l // gcd(l, t) * t
            lcms[mask] = l
        INF = float('inf')
        dp = [INF]*full
        dp[0] = 0
        for num in nums:
            costs = [0]*full
            for sub in range(1, full):
                L = lcms[sub]
                costs[sub] = (L - num % L) % L
            ndp = dp[:]
            for mask in range(full):
                d = dp[mask]
                if d == INF:
                    continue
                for sub in range(1, full):
                    nm = mask | sub
                    v = d + costs[sub]
                    if v < ndp[nm]:
                        ndp[nm] = v
            dp = ndp
        return dp[full-1]

