        Yh = Y >> 15
        return ((((X @ Yh) % mod) << 15) + (X @ Yl)) % mod

    def matpow(M, e, mod):
        R = np.eye(N, dtype=np.int64) % mod
        M = M % mod
        while e:
            if e & 1:
                R = mul(R, M, mod)
            M = mul(M, M, mod)
            e >>= 1
        return R

