        if (N-1) % A != 0:
            print("No"); return
        for i in range(M):
            L = Ls[i]; R = Rs[i]
            j = L + ((1 - L) % A)
            if j <= R:
                print("No"); return
        print("Yes"); return

    FULL = (1 << B) - 1
    CHECK = FULL ^ ((1 << (A-1)) - 1)

    fs = {FULL: 0}
    LEV = 22
    lifts = [dict() for _ in range(LEV)]

    def lift(k, m):
        d = lifts[k]
        r = d.get(m)
        if r is None:
            if k == 0:
                r = ((m << 1) | (1 if m & CHECK else 0)) & FULL
            else:
                r = lift(k-1, lift(k-1, m))
            d[m] = r
        return r

    def advance(m, t):
        k = 0
        while t:
            if t & 1:
                m = lift(k, m)
            t >>= 1
            k += 1
        return m

    def full_steps(m0):
        path = []
        m = m0
        cnt = 0
        while m not in fs:
            path.append(m)
            m = ((m << 1) | (1 if m & CHECK else 0)) & FULL
            cnt += 1
            if cnt > 100000:
                break
        base = fs.get(m, 0)
        for x in reversed(path):
            base += 1
            fs[x] = base
        return fs.get(m0, base)

    cur = 1
    m = 1
    idx = 0
    ok = True
    while cur < N:
        while idx < M and Rs[idx] <= cur:
            idx += 1
        if idx < M and Ls[idx] <= cur + 1:
            R = Rs[idx]
            ln = R - cur
            if ln >= B:
                ok = False
                break
            m = (m << ln) & FULL
            cur = R
