class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        mx = max(nums)
        if mx <= 0:
            return mx

        # plain Kadane (no removal)
        ans = -10**18
        cur = 0
        for a in nums:
            cur = (cur if cur > 0 else 0) + a
            if cur > ans:
                ans = cur

        NEG = -10**18
        s = {}
        heap = []
        for a in nums:
            if a < 0 and a not in s:
                s[a] = 0
                heap.append((0, a))
        if not heap:
            return ans
        heapq.heapify(heap)

        C = 0
        D = NEG
        for a in nums:
            if a < 0:
                sa = s[a]
                cu = sa + C
                if D > cu:
                    cu = D
                if cu < 0:
                    cu = 0
                C += a
                D = (D if D > 0 else 0) + a
                ns = cu - C
                s[a] = ns
                heapq.heappush(heap, (-ns, a))
            else:
                C += a
                D = (D if D > 0 else 0) + a
            # lazy deletion
            while -heap[0][0] != s[heap[0][1]]:
                heapq.heappop(heap)
            m = -heap[0][0] + C
            if D > m:
                m = D
            if m > ans:
                ans = m
        return ans

