class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def cost(k):
            if k == 1:
                c0 = 0
                c1 = 0
                for i, ch in enumerate(s):
                    if ch != ('0' if i % 2 == 0 else '1'):
                        c0 += 1
                    if ch != ('1' if i % 2 == 0 else '0'):
                        c1 += 1
                return min(c0, c1)
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                total += (j - i) // (k + 1)
                i = j
            return total

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        big = 0
        small = []
        for x in nums:
            if x > T:
                big += 1
            else:
                small.append(x)
        if not small:
            return big
        parent = list(range(T + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        rep = [0] * (T + 1)
        small.sort()
        for d in small:
            for L in range(d, T + 1, d):
                r = rep[L]
                if r:
                    # union r and d
                    ra = find(r)
                    rb = find(d)
                    if ra != rb:
                        if ra < rb:
                            parent[rb] = ra
                        else:
                            parent[ra] = rb
                else:
                    rep[L] = d
        roots = set()
        for x in small:
            roots.add(find(x))
        return big + len(roots)
